namespace LavaFacil.GraphQL.GraphQL;

public sealed class Cliente { public int IdCliente { get; set; } public string Cedula { get; set; } = ""; public string Nombre { get; set; } = ""; public string Apellidos { get; set; } = ""; public string Telefono { get; set; } = ""; public string Email { get; set; } = ""; public string? Direccion { get; set; } public DateTime FechaRegistro { get; set; } public bool Activo { get; set; } }
public sealed class Empleado { public int IdEmpleado { get; set; } public string Cedula { get; set; } = ""; public string Nombre { get; set; } = ""; public string Apellidos { get; set; } = ""; public string Telefono { get; set; } = ""; public string Email { get; set; } = ""; public string Cargo { get; set; } = ""; public DateTime FechaIngreso { get; set; } public bool Activo { get; set; } }
public sealed class Usuario { public int IdUsuario { get; set; } public string NombreUsuario { get; set; } = ""; public string TipoUsuario { get; set; } = ""; public int? IdCliente { get; set; } public int? IdEmpleado { get; set; } public bool Activo { get; set; } public DateTime FechaCreacion { get; set; } }
public sealed class Servicio { public int IdServicio { get; set; } public string NombreServicio { get; set; } = ""; public string? Descripcion { get; set; } public string TipoCobro { get; set; } = ""; public decimal PrecioBase { get; set; } public decimal CantidadIncluida { get; set; } public decimal PrecioAdicional { get; set; } public bool Activo { get; set; } }
public sealed class Pedido { public int IdPedido { get; set; } public int IdCliente { get; set; } public DateTime FechaPedido { get; set; } public DateTime? FechaEntregaEstimada { get; set; } public string Estado { get; set; } = ""; public decimal Total { get; set; } public string? Observaciones { get; set; } }
public sealed class DetallePedido { public int IdDetalle { get; set; } public int IdPedido { get; set; } public int IdServicio { get; set; } public decimal Cantidad { get; set; } public decimal PrecioBase { get; set; } public decimal MontoAdicional { get; set; } public decimal Subtotal { get; set; } }
public sealed class Pago { public int IdPago { get; set; } public int IdPedido { get; set; } public DateTime FechaPago { get; set; } public decimal Monto { get; set; } public string MetodoPago { get; set; } = ""; public string EstadoPago { get; set; } = ""; public string? Referencia { get; set; } }
public sealed class Recoleccion { public int IdRecoleccion { get; set; } public int IdPedido { get; set; } public string Direccion { get; set; } = ""; public DateTime FechaProgramada { get; set; } public string Estado { get; set; } = ""; public string? Observaciones { get; set; } }
public sealed class Promocion { public int IdPromocion { get; set; } public int IdServicio { get; set; } public string NombrePromocion { get; set; } = ""; public string? Descripcion { get; set; } public decimal PorcentajeDescuento { get; set; } public DateTime FechaInicio { get; set; } public DateTime FechaFin { get; set; } public bool Activa { get; set; } }
public sealed class Inventario { public int IdInventario { get; set; } public string NombreProducto { get; set; } = ""; public string? Descripcion { get; set; } public decimal Cantidad { get; set; } public string UnidadMedida { get; set; } = ""; public decimal CantidadMinima { get; set; } public DateTime FechaActualizacion { get; set; } public bool Activo { get; set; } }
public sealed class LoginRow { public bool LoginValido { get; set; } public int? IdUsuario { get; set; } public string? NombreUsuario { get; set; } public string? TipoUsuario { get; set; } public int? IdCliente { get; set; } public int? IdEmpleado { get; set; } }
public sealed record LoginPayload(bool Exito, string Mensaje, string? Token, int? IdUsuario, string? NombreUsuario, string? Rol);
public sealed record OperationResult(bool Exito, string Mensaje);
